export const page="<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"color-scheme\" content=\"light\">\n  <title>布料花型助手</title>\n  <style>\n    :root { --blue:#2563eb; --blue-soft:#eff5ff; --ink:#14213d; --muted:#718096; --line:#e5ebf4; --green:#148565; --red:#c53a49; }\n    * { box-sizing:border-box; }\n    body { margin:0; background:#f5f8fc; color:var(--ink); font-family:Inter,\"Segoe UI\",\"Microsoft YaHei\",sans-serif; line-height:1.6; }\n    button,textarea,select { font:inherit; }\n    .preset-grid { display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-bottom:12px; }\n    .preset-grid select { display:block; width:100%; border:1px solid #dce5f0; border-radius:8px; padding:9px; background:white; font-size:12px; color:var(--ink); }\n    .preset-wide { grid-column:1 / -1; }\n    button,a,textarea { -webkit-tap-highlight-color:transparent; }\n    button { cursor:pointer; }\n    button:disabled { cursor:not-allowed; opacity:.55; }\n    button:focus-visible,a:focus-visible { outline:3px solid #a9c8ff; outline-offset:4px; }\n    [hidden] { display:none !important; }\n    .shell { max-width:1120px; margin:auto; padding:0 28px; }\n    header { display:flex; justify-content:space-between; align-items:center; min-height:96px; gap:16px; }\n    .brand { display:flex; align-items:center; gap:11px; font-size:19px; font-weight:700; letter-spacing:-.4px; }\n    .brand-icon { display:grid; place-items:center; width:38px; height:38px; color:white; background:var(--blue); border-radius:12px; box-shadow:0 5px 12px #2563eb22; }\n    .brand-icon svg { width:21px; height:21px; }\n    .connection { display:flex; align-items:center; gap:7px; color:var(--muted); font-size:12px; }\n    .connection-dot { width:7px; height:7px; border-radius:50%; background:var(--green); }\n    .connection.offline .connection-dot { background:#d48b26; }\n    .hero { padding:29px 0 31px; }\n    .eyebrow { color:var(--blue); font-size:12px; font-weight:700; letter-spacing:2px; }\n    h1 { margin:10px 0 9px; font-size:clamp(28px,4vw,39px); line-height:1.35; font-weight:750; letter-spacing:-1px; }\n    .hero p { color:var(--muted); margin:0; font-size:14px; }\n    .layout { display:grid; grid-template-columns:minmax(0, .95fr) minmax(0, 1.25fr); align-items:start; gap:24px; padding-bottom:52px; }\n    .card { background:white; border:1px solid var(--line); border-radius:19px; box-shadow:0 8px 30px #25447004; overflow:hidden; }\n    .composer { padding:27px; }\n    .card-title { margin:0; font-size:17px; font-weight:700; }\n    .card-desc { margin:5px 0 21px; font-size:13px; color:var(--muted); }\n    label { display:block; font-size:13px; font-weight:600; margin-bottom:9px; }\n    textarea { display:block; width:100%; min-height:230px; resize:vertical; border:1px solid #dce5f0; border-radius:12px; padding:15px; background:#fbfcfe; color:var(--ink); font-size:14px; line-height:1.8; outline:none; transition:border-color .15s, box-shadow .15s; }\n    textarea:focus { border-color:#7aabff; box-shadow:0 0 0 3px #2563eb10; }\n    textarea::placeholder { color:#95a3b7; }\n    textarea:disabled { color:#62718b; background:#f3f6fa; }\n    .input-meta { display:flex; justify-content:space-between; gap:10px; margin-top:9px; font-size:11px; color:#8b98ac; }\n    .examples { display:flex; flex-wrap:wrap; gap:7px; margin:21px 0; }\n    .example { background:white; border:1px solid var(--line); border-radius:7px; padding:6px 10px; color:#62718b; font-size:12px; }\n    .example:hover:not(:disabled) { border-color:#b7d0fd; color:var(--blue); background:var(--blue-soft); }\n    .primary { display:flex; align-items:center; justify-content:center; gap:9px; width:100%; min-height:47px; border:0; border-radius:10px; background:var(--blue); color:white; font-size:14px; font-weight:600; box-shadow:0 4px 8px #2563eb15; }\n    .primary:hover:not(:disabled) { background:#1c55d5; }\n    .primary svg { width:17px; height:17px; }\n    .hint { color:var(--muted); font-size:11px; margin:12px 0 0; text-align:center; }\n    .reference { margin-top:18px; padding:14px; border:1px dashed #b7d0fd; border-radius:10px; background:#fbfcfe; }\n    .reference p { margin:7px 0; font-size:11px; color:var(--muted); }\n    #referencePreview { display:block; max-width:100%; max-height:150px; margin:10px 0; border-radius:8px; }\n    #referenceFile { width:100%; font:inherit; font-size:12px; }\n    .result-head { padding:24px 25px 20px; display:flex; align-items:center; justify-content:space-between; gap:12px; }\n    .badge { padding:5px 10px; border-radius:6px; background:#f2f5f9; color:#7a879b; font-size:11px; white-space:nowrap; }\n    .badge[data-status=\"queued\"],.badge[data-status=\"running\"],.badge[data-status=\"pending\"] { background:var(--blue-soft); color:var(--blue); }\n    .badge[data-status=\"done\"] { color:var(--green); background:#edf9f4; }\n    .badge[data-status=\"error\"] { color:var(--red); background:#fff0f1; }\n    .preview { margin:0 25px; min-height:310px; border:1px solid var(--line); border-radius:12px; background:linear-gradient(145deg,#f8fbff,#f3f7fc); display:flex; align-items:center; justify-content:center; overflow:hidden; }\n    .placeholder { max-width:310px; padding:36px 24px; text-align:center; }\n    .placeholder-icon { display:grid; place-items:center; margin:0 auto 16px; width:65px; height:65px; border:1px solid #dae6f8; border-radius:18px; color:#6f9bd8; background:white; }\n    .placeholder-icon svg { width:30px; height:30px; }\n    .placeholder h3 { font-size:15px; font-weight:600; margin:0 0 6px; }\n    .placeholder p { margin:0; font-size:12px; color:var(--muted); }\n    .busy .placeholder-icon { color:var(--blue); animation:breathe 2s ease-in-out infinite; }\n    @keyframes breathe { 50% { box-shadow:0 0 0 9px #2563eb08; } }\n    @media (prefers-reduced-motion:reduce) { .busy .placeholder-icon { animation:none; } }\n    #resultImage { display:block; width:100%; height:auto; max-height:650px; object-fit:contain; background:#eef3f9; }\n    .result-actions { display:flex; justify-content:flex-end; align-items:center; gap:10px; padding:15px 25px 0; }\n    #reviewActions { flex-wrap:wrap; justify-content:flex-start; }\n    .secondary { display:inline-flex; align-items:center; justify-content:center; gap:6px; padding:7px 12px; border:1px solid #dce5f0; border-radius:7px; background:white; color:var(--blue); text-decoration:none; font-size:12px; }\n    .secondary:hover { background:var(--blue-soft); }\n    .secondary svg { width:15px; height:15px; }\n    .details { padding:21px 25px 24px; }\n    .stage-row { display:flex; gap:10px; align-items:baseline; justify-content:space-between; }\n    #stageText { margin:0; font-size:13px; color:#485c77; overflow-wrap:anywhere; }\n    #queueText { font-size:11px; color:var(--muted); white-space:nowrap; }\n    .error-message { font-size:12px; color:var(--red); background:#fff5f6; border-radius:8px; padding:11px 13px; margin:12px 0 0; white-space:pre-wrap; overflow-wrap:anywhere; }\n    #networkMessage { font-size:12px; color:#a06c23; margin:10px 0 0; }\n    .log { list-style:none; padding:0; margin:17px 0 0; border-top:1px solid #edf1f7; max-height:185px; overflow:auto; }\n    .log li { display:flex; gap:12px; align-items:baseline; font-size:11px; color:#7c8ba0; padding-top:10px; overflow-wrap:anywhere; }\n    .log time { flex:0 0 auto; color:#a0acbd; font-variant-numeric:tabular-nums; }\n    .task-id { margin:14px 0 0; font-size:10px; color:#a0acbd; overflow-wrap:anywhere; }\n    footer { border-top:1px solid var(--line); padding:20px 0 26px; color:#9aa6b8; font-size:11px; }\n    @media (max-width:760px) { .shell { padding:0 18px; } header { min-height:77px; } .hero { padding:19px 0 25px; } .layout { grid-template-columns:1fr; gap:18px; padding-bottom:30px; } .composer { padding:22px; } textarea { min-height:190px; } .result-head { padding:21px 21px 17px; } .preview { margin:0 21px; min-height:250px; } .details { padding:19px 21px 22px; } .result-actions { padding:14px 21px 0; } }\n    @media (max-width:380px) { .connection { font-size:10px; } .brand { font-size:17px; } .input-meta span:first-child { display:none; } }\n  .reference-card {display:inline-flex;flex-direction:column;width:30%;padding:6px;vertical-align:top;overflow-wrap:anywhere}.reference-card img {max-width:100%;height:110px;object-fit:contain}.task-card {text-align:left} dialog::backdrop {background:#0006}\n    body.needs-attention::after {content:\"\";position:fixed;inset:0;border:6px solid #dc2626;box-shadow:inset 0 0 22px #dc262644;pointer-events:none;z-index:1000;}\n    .attention-banner {position:sticky;top:0;z-index:20;margin:0 0 20px;padding:18px 20px;border:3px solid #dc2626;border-radius:12px;background:#fff1f2;color:#991b1b;box-shadow:0 5px 20px #dc262622;font-size:16px;font-weight:600;}\n    .attention-banner p {margin:0 0 10px;white-space:pre-wrap;overflow-wrap:anywhere;}\n    .alert-controls {display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:18px;}\n    .alert-controls label {margin:0;font-size:13px;}\n    .task-card[data-status=\"review\"],.task-card[data-status=\"error\"] {border:2px solid #dc2626;background:#fff1f2;color:#991b1b;}\n    .error-message {border:2px solid #dc2626;font-size:15px;font-weight:600;}\n    .task-sections {padding:22px 25px 0;display:grid;gap:22px;}\n    .task-section h3 {margin:0 0 12px;font-size:16px;}\n    .task-section h3 span {margin-left:8px;color:var(--muted);font-size:12px;}\n    .work-task {padding:14px;border:1px solid var(--line);border-radius:10px;margin-bottom:10px;}\n    .work-task p {margin:9px 0;font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;}\n    .work-task small,.task-empty {font-size:12px;color:var(--muted);}\n    .work-task-actions {display:flex;gap:8px;flex-wrap:wrap;margin-top:10px;}\n    .work-task[data-status=\"review\"] {border:2px solid #dc2626;background:#fff1f2;}\n  </style>\n</head>\n<body><div id=\"cloudWorkerState\" role=\"status\" style=\"padding:12px;text-align:center;background:#edf4ff;color:#244677\">正在读取虚拟机状态…</div>\n  <div class=\"shell\">\n    <header>\n      <div class=\"brand\"><span class=\"brand-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z\"/></svg></span>画图助手 <span id=\"appVersion\" aria-label=\"当前版本 v0.2.7\" style=\"font-size:11px;font-weight:500;color:var(--muted);padding:3px 7px;background:#edf1f7;border-radius:6px;white-space:nowrap\">v0.2.7</span></div>\n      <div id=\"connection\" class=\"connection\"><span class=\"connection-dot\"></span><span id=\"connectionText\">准备就绪</span></div>\n    </header>\n    <section class=\"hero\">\n      <div class=\"eyebrow\">远程创作</div>\n      <h1>把灵感变成布料花型。</h1>\n      <p>选择连续方式与花型主题，或上传参考图片，生成可用于印花的平面设计。</p>\n    </section>\n    <div class=\"alert-controls\">\n      <label><input id=\"voiceEnabled\" type=\"checkbox\" checked> 语音提醒</label>\n      <button id=\"repeatAttention\" class=\"secondary\" type=\"button\">试听 / 重播提醒</button>\n      <span style=\"font-size:12px;color:var(--muted)\">首次使用请点试听启用声音，红框提示始终保留。</span>\n    </div>\n    <section id=\"attentionBanner\" class=\"attention-banner\" role=\"alert\" aria-live=\"assertive\" hidden>\n      <p id=\"attentionText\"></p>\n      <button id=\"dismissAttention\" class=\"secondary\" type=\"button\">知道了</button>\n      <a id=\"reportAttention\" href=\"/report-bug\" hidden>报告此问题</a>\n      <button id=\"viewAttentionTask\" class=\"secondary\" type=\"button\" hidden>查看需要处理的任务</button>\n    </section>\n    <main class=\"layout\">\n      <section class=\"card composer\" aria-labelledby=\"composeTitle\">\n        <h2 id=\"composeTitle\" class=\"card-title\">设计布料花型</h2>\n        <p class=\"card-desc\">默认四方连续。填入预设后，可以继续修改纹样、色彩、疏密与风格。</p>\n        <form id=\"promptForm\">\n          <label for=\"fabricTool\">设计工具预设</label>\n          <select id=\"fabricTool\" style=\"width:100%;padding:10px;border:1px solid #dce5f0;border-radius:8px;margin-bottom:10px\"></select>\n          <p id=\"toolHint\" class=\"card-desc\" style=\"margin-bottom:12px\">按连续方式和花型主题设计布料。</p>\n          <div class=\"preset-grid\">\n            <div><label for=\"fabricLayout\">连续方式</label><select id=\"fabricLayout\"></select></div>\n            <div><label for=\"fabricTheme\">花型主题</label><select id=\"fabricTheme\"></select></div>\n            <div class=\"preset-wide\"><label for=\"fabricPalette\">配色方向</label><select id=\"fabricPalette\"></select></div>\n          </div>\n          <button id=\"applyPreset\" class=\"secondary\" type=\"button\">填入完整布料提示词</button>\n          <label for=\"prompt\" style=\"margin-top:14px\">花型提示词（可编辑）</label>\n          <textarea id=\"prompt\" name=\"prompt\" placeholder=\"例如：保留参考图的小花与叶片，重新设计成四方连续花型，左右及上下边缘能无缝衔接，柔和蓝白配色，平面印花原稿。\" required></textarea>\n          <div class=\"input-meta\"><span>支持中文与多行描述</span><span id=\"characterCount\">0 字</span></div>\n          <div class=\"reference\">\n            <label for=\"referenceFile\">参考图片（可选）</label>\n            <input id=\"referenceFile\" type=\"file\" multiple accept=\"image/png,image/jpeg,image/webp\">\n            <p id=\"referenceName\">支持 0～3 张 PNG、JPEG 或 WEBP，每张最大 20 MB。</p>\n            <div id=\"referencePreviews\"></div>\n            <button id=\"removeReference\" type=\"button\" class=\"secondary\" hidden>移除图片</button>\n          </div>\n          <div class=\"examples\" aria-label=\"示例提示词\">\n            <button type=\"button\" class=\"example\" data-theme=\"ditsy\">小碎花</button>\n            <button type=\"button\" class=\"example\" data-theme=\"geometric\">几何花型</button>\n            <button type=\"button\" class=\"example\" data-theme=\"kids\">童趣花型</button>\n            <button type=\"button\" class=\"example\" data-theme=\"reference\">参考图再设计</button>\n          </div>\n          <button id=\"submitButton\" class=\"primary\" type=\"submit\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><path d=\"m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z\"/></svg><span id=\"submitLabel\">开始生成</span></button>\n          <p class=\"hint\">提交后可立即继续创建任务。桌面操作按顺序执行，各任务互不影响。</p>\n        </form>\n      </section>\n      <section class=\"card\" aria-labelledby=\"resultTitle\">\n        <div class=\"task-sections\">\n          <section class=\"task-section\" aria-labelledby=\"queuedTitle\">\n            <h3 id=\"queuedTitle\">排队中 <span id=\"queuedCount\">0</span></h3>\n            <p class=\"task-empty\">包含正在提交、排队、执行和等待确认的任务。</p>\n            <div id=\"queuedList\"></div><p id=\"queuedEmpty\" class=\"task-empty\">暂无待处理任务。</p>\n          </section>\n          <section class=\"task-section\" aria-labelledby=\"completedTitle\">\n            <h3 id=\"completedTitle\">已完成待下载 <span id=\"completedCount\">0</span></h3>\n            <p class=\"task-empty\">下载后从这里移除，生成记录仍保留。</p>\n            <div id=\"completedList\"></div><p id=\"completedEmpty\" class=\"task-empty\">暂无待下载图片。</p>\n          </section>\n        </div>\n        <div class=\"result-head\"><h2 id=\"resultTitle\" class=\"card-title\">生成结果</h2><span id=\"statusBadge\" class=\"badge\" data-status=\"idle\">等待任务</span></div>\n        <p><a id=\"generationLog\" hidden download>下载本次生成日志</a></p>\n        <div id=\"preview\" class=\"preview\">\n          <div id=\"placeholder\" class=\"placeholder\">\n            <div class=\"placeholder-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"><rect x=\"4\" y=\"5\" width=\"24\" height=\"22\" rx=\"4\"/><circle cx=\"11\" cy=\"12\" r=\"2.5\"/><path d=\"m5 23 7-7 5 5 4-5 6 7\"/></svg></div>\n            <h3 id=\"previewTitle\">画面从你的想象开始</h3><p id=\"previewDescription\">提交提示词后，生成原图会显示在这里。</p>\n          </div>\n          <img id=\"resultImage\" alt=\"电脑端生成完成后的原图\" hidden>\n        </div>\n        <div id=\"resultActions\" class=\"result-actions\" hidden>\n          <button id=\"reloadImage\" class=\"secondary\" type=\"button\" hidden>重新加载原图</button>\n          <a id=\"downloadLink\" class=\"secondary\" download><svg viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\"><path d=\"M10 3v9m-4-4 4 4 4-4M4 13v4h12v-4\"/></svg>下载原图</a>\n        </div>\n        <div id=\"reviewActions\" class=\"result-actions\" hidden>\n          <button id=\"retryDownload\" type=\"button\" class=\"secondary\">已经生成</button>\n          <button id=\"keepWaiting\" type=\"button\" class=\"secondary\">继续等待</button><button id=\"endGeneration\" type=\"button\" class=\"secondary\">生成已结束</button>\n        </div>\n        <div class=\"details\" aria-live=\"polite\" aria-atomic=\"false\">\n          <div class=\"stage-row\"><p id=\"stageText\">准备好后，点击「开始生成」。</p><span id=\"queueText\" hidden></span></div>\n          <p id=\"errorMessage\" class=\"error-message\" hidden></p>\n          <p id=\"networkMessage\" hidden></p>\n          <ul id=\"stageLog\" class=\"log\" aria-label=\"任务进度\" hidden></ul>\n          <p id=\"taskId\" class=\"task-id\" hidden></p>\n        </div>\n      </section>\n    </main>\n    <section class=\"card\" style=\"padding:24px;margin-bottom:30px\" aria-labelledby=\"historyTitle\">\n      <h2 id=\"historyTitle\">生成记录</h2>\n      <p>查看以前的提示词、状态和结果。记录保存在执行电脑，服务器重启后仍可查看。</p>\n      <select id=\"historyFilter\" aria-label=\"按状态筛选生成记录\">\n        <option value=\"\">全部记录</option><option value=\"done\">生成成功</option><option value=\"not_generated\">未生成图片</option><option value=\"error\">执行失败</option><option value=\"queued\">排队中</option><option value=\"running\">正在执行</option><option value=\"review\">等待人工确认</option>\n      </select>\n      <button id=\"refreshHistory\" class=\"secondary\" type=\"button\">刷新记录</button>\n      <p id=\"historyMessage\" aria-live=\"polite\"></p>\n      <div id=\"historyList\" style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:14px\"></div>\n      <button id=\"historyPrevious\" class=\"secondary\" type=\"button\">上一页</button>\n      <span id=\"historyPage\"></span>\n      <button id=\"historyNext\" class=\"secondary\" type=\"button\">下一页</button>\n    </section>\n    <footer>生成完成后可下载原图，或继续描述下一幅画面。</footer>\n  </div>\n  <dialog id=\"endDialog\" style=\"max-width:560px;border:1px solid #dce5f0;border-radius:12px;padding:24px\">\n    <h3>确认结束本次生成任务？</h3>\n    <p>你点击了“生成已结束”。</p>\n    <p>此操作适用于 AI 实际上没有启动图片生成任务的情况，例如 AI 只回复了文字、要求补充参考图片、询问其他问题，或者当前页面明显没有进入图片生成状态。</p>\n    <p>确认后，本次任务将立即结束。系统不会继续等待图片生成，也不会继续检测完成标记。如果你仍然需要生成这张图片，需要重新提交一次生成任务。</p>\n    <p>建议你在重新生成之前检查并适当修改提示词。AI 本次没有启动图片生成，可能与提示词内容、参考图片要求或当前指令的理解有关。如果直接使用完全相同的内容再次提交，有可能再次出现相同情况。</p>\n    <button id=\"cancelEnd\" type=\"button\" class=\"secondary\">取消，继续当前任务</button>\n    <button id=\"confirmEnd\" type=\"button\" class=\"secondary\">确认结束任务</button>\n  </dialog>\n  <script>window.workflowConfig={catalog:{\"tools\": [{\"id\": \"custom\", \"label\": \"自定义提示词\", \"instruction\": \"\", \"requires_reference\": false}, {\"id\": \"fabric\", \"label\": \"布料花型设计\", \"instruction\": \"\", \"requires_reference\": false}, {\"id\": \"extract\", \"label\": \"花型提取／印花提取\", \"requires_reference\": true, \"instruction\": \"从上传的布料、服装或家纺照片中提取印花纹样。只保留原图中的花朵、枝叶、几何纹样或其他印花元素，忠实保留造型、线条与配色。去掉布料底色、经纬布纹、纤维肌理、褶皱、光照阴影、服装轮廓、人物及背景；校正透视，使纹样平整正视。恢复被轻微褶皱干扰的线条，尽量完整提取可见元素，不随意改变花型。输出清晰干净的平面纹样图，要求透明背景 PNG，无文字、水印、边框或产品展示。\"}, {\"id\": \"seamless\", \"label\": \"四方连续图\", \"requires_reference\": false, \"instruction\": \"根据参考图或文字设计四方连续图。保留主要纹样、配色与风格，重新排列为一个正方形循环单元；左右边缘、上下边缘必须准确对应续接，四个角衔接自然，重复平铺后没有明显接缝。只输出一个可平铺的单元，不输出四宫格、网格演示、服装效果图或标注。\"}, {\"id\": \"style\", \"label\": \"风格转换\", \"requires_reference\": true, \"instruction\": \"以参考图为基础进行艺术风格转换，保留主体结构、图案构成、比例与辨识度，把线条和色彩转为细腻自然的手绘水彩风格。输出正面平视的干净花型原稿，不增加模特、产品展示或无关场景。具体风格可按我下面的补充要求调整。\"}, {\"id\": \"edit\", \"label\": \"AI 修图 · 自定义\", \"requires_reference\": true, \"instruction\": \"按我描述的要求修改参考图，保持未要求修改的主体、构图、花型和配色一致，只调整指定部分。修复应自然、细节清楚，不擅自添加文字、水印或其他元素。具体修改要求：\"}, {\"id\": \"remove_texture\", \"label\": \"AI 去布纹\", \"requires_reference\": true, \"instruction\": \"去除参考图中的经纬纱线、布纹、纤维肌理、褶皱和光照阴影，同时保留印花图案原有轮廓、细节和配色。校正透视与拉伸变形，让图案成为平整正视、色彩均匀的印花原稿。只清理布料造成的干扰，不把花型内部原本的手绘笔触或设计纹理一并抹掉。\"}, {\"id\": \"redraw\", \"label\": \"高清重绘\", \"requires_reference\": true, \"instruction\": \"忠实重绘参考图中的花型，保留原有构图、纹样轮廓、配色和元素数量，提高线条清晰度，修复模糊、锯齿与压缩噪点，恢复合理的细节。输出尽可能高分辨率的干净平面原稿，不改变设计、不新增装饰、无文字或水印。\"}, {\"id\": \"expand\", \"label\": \"扩图\", \"requires_reference\": true, \"instruction\": \"在参考图周围自然扩展画面，保持原始区域、风格、配色、纹样大小和密度一致，新增内容与原图连续衔接，不重复明显的局部，不出现突兀边界。用于布料花型时只扩展平面花型，不生成服装、模特或产品场景。扩展方向及比例按补充要求执行。\"}, {\"id\": \"similar\", \"label\": \"相似花型再设计\", \"requires_reference\": true, \"instruction\": \"参考原图的主题、配色、艺术风格、纹样尺度与密度，重新设计一张协调但有变化的布料花型。保留整体风格，适度改变元素姿态、细节和排列方式，输出单张新设计的平面原稿，无产品展示、文字或水印。\"}, {\"id\": \"remove_rhinestones\", \"label\": \"去除烫钻\", \"requires_reference\": true, \"instruction\": \"去除参考图中的烫钻、亮片及其高光反射，修复被遮挡的原有印花线条与色彩，保持主要图案的造型、布局和配色。修补区域与周围自然一致，不生成新的闪光颗粒、金属点或额外装饰。\"}, {\"id\": \"vector_style\", \"label\": \"矢量风格重绘 · 图片\", \"requires_reference\": true, \"instruction\": \"把参考图重绘为干净的矢量插画视觉风格：轮廓清晰、曲线平滑、色块干净、颜色层次简洁，忠实保留主要造型与配色。输出单张平面图片，方便后续描摹矢量化；不生成文件界面、格式标签、文字或水印。\"}, {\"id\": \"cutout\", \"label\": \"抠图 · 单图\", \"requires_reference\": true, \"instruction\": \"精细提取参考图中的主体或印花元素，移除无关背景，保留主体完整轮廓、细节、边缘与原有色彩；不留背景残片、白边或锯齿。输出透明背景 PNG，不添加阴影、文字、水印或外框。\"}, {\"id\": \"try_on\", \"label\": \"服装换装效果\", \"requires_reference\": true, \"instruction\": \"以参考图片中的人物或模特为基础，根据我的服装描述更换穿着，保留人物身份、面部、姿态、身材比例及原有场景。服装结构和布料纹样贴合身体，褶皱、光线与遮挡自然。服装或花型要求：\"}, {\"id\": \"hanging\", \"label\": \"服装挂拍／立体效果\", \"requires_reference\": true, \"instruction\": \"参考服装或花型图片，生成一张干净专业的服装挂拍或立体商品展示图片。保留服装款式、剪裁、主要配色及纹样，比例准确，面料和光照自然，背景简洁，边缘清楚。具体服装品类、角度及背景要求：\"}, {\"id\": \"scene\", \"label\": \"参考场景再设计\", \"requires_reference\": true, \"instruction\": \"参考上传图片的构图、场景、光照与整体风格，根据我的要求生成新的场景或商品展示图。画面完整、比例自然，保留需要参考的主要特征；不添加无关文字、水印、界面元素或商标。具体要求：\"}], \"layouts\": [{\"id\": \"four_way\", \"label\": \"四方连续 · 无缝平铺\", \"instruction\": \"设计可印在布料上的四方连续花型，输出一张正方形循环单元。左右边缘、上下边缘的图案、位置及颜色必须衔接，横向和纵向重复平铺后自然连续，不出现拼接缝。边缘切开的元素要在对侧对应续接。不要画四宫格或多张拼接示意图。\"}, {\"id\": \"horizontal\", \"label\": \"二方连续 · 横向\", \"instruction\": \"设计布料用横向二方连续花型，输出一张横向循环单元。左右边缘的图案及颜色必须对应衔接，横向重复时自然连续；上下边缘保持完整，不要求纵向循环。\"}, {\"id\": \"vertical\", \"label\": \"二方连续 · 纵向\", \"instruction\": \"设计布料用纵向二方连续花型，输出一张纵向循环单元。上下边缘的图案及颜色必须对应衔接，纵向重复时自然连续；左右边缘保持完整，不要求横向循环。\"}, {\"id\": \"half_drop\", \"label\": \"半落位连续 · 错位排列\", \"instruction\": \"设计布料用半落位连续花型，相邻列中的主纹样错开半个排列节距，节奏自然。将错位排列完整收纳到一张矩形循环单元中，使最终单元上下左右都能直接衔接平铺，无明显接缝；不画拼接示意图。\"}, {\"id\": \"placement\", \"label\": \"定位花 · 单独图案\", \"instruction\": \"设计布料用定位花图案：一个完整的主花型，主次分明、构图完整，周围保留适当留白。主图案不要被边缘裁切，适合放在衣片、围巾或布料指定位置；输出单个完整设计。\"}, {\"id\": \"border\", \"label\": \"边饰 · 连续花边\", \"instruction\": \"设计布料用连续边饰花型，装饰纹样沿横向形成清楚的花边层次，左右边缘必须能重复衔接，横向平铺自然连续。上下边缘保持整洁，适合布料边缘或裙摆的装饰带。\"}], \"themes\": [{\"id\": \"ditsy\", \"label\": \"小碎花\", \"instruction\": \"细小的花朵、花苞与纤细枝叶，元素大小有变化，疏密均衡，清新细腻，适合连衣裙与轻薄布料。\"}, {\"id\": \"large_floral\", \"label\": \"大花卉\", \"instruction\": \"大朵花卉与舒展枝叶，层次清楚，花型错落排布，优雅且有装饰感，适合服装与家纺。\"}, {\"id\": \"botanical\", \"label\": \"植物枝叶\", \"instruction\": \"自然舒展的叶片、枝条与小花，植物形态细腻，方向有变化，整体平衡，清新自然。\"}, {\"id\": \"tropical\", \"label\": \"热带植物\", \"instruction\": \"龟背竹、棕榈叶与热带花卉，舒展而有层次，明快但配色协调，具有夏日气息。\"}, {\"id\": \"geometric\", \"label\": \"几何图案\", \"instruction\": \"圆形、弧线、三角形和简洁几何块面，线条清晰，排列有节奏，现代而简洁。\"}, {\"id\": \"stripes\", \"label\": \"条纹\", \"instruction\": \"宽窄搭配的条纹，间距和粗细有清晰规律，线条干净，适合服装印花；不要加入文字或标志。\"}, {\"id\": \"dots\", \"label\": \"波点\", \"instruction\": \"大小协调的圆形波点，排列规律或轻微错落，整体密度均衡，干净简洁、经典耐看。\"}, {\"id\": \"checks\", \"label\": \"格纹\", \"instruction\": \"经纬交织感的格纹，线宽和间距有清晰规律，色块边界干净，经典织物风格。\"}, {\"id\": \"kids\", \"label\": \"童趣动物\", \"instruction\": \"简洁可爱的动物、小星星与小植物，轮廓清楚，造型温和，元素错落但不过密，适合童装与儿童家纺。\"}, {\"id\": \"fruit\", \"label\": \"水果花型\", \"instruction\": \"柠檬、草莓或其他协调搭配的水果，辅以小叶片和花朵，生动清新，适合夏季服装与餐厨布料。\"}, {\"id\": \"paisley\", \"label\": \"佩斯利腰果花\", \"instruction\": \"经典佩斯利腰果纹与细密装饰花纹，弧线流畅，主纹样和小纹样搭配，精致有序。\"}, {\"id\": \"abstract\", \"label\": \"抽象肌理\", \"instruction\": \"抽象笔触、点线与柔和色块，保留绘画感但画面干净，层次自然，适合艺术感布料印花。\"}, {\"id\": \"reference\", \"label\": \"参考图再设计\", \"instruction\": \"保留参考图的主要纹样、主体造型与配色，提取可用于布料的元素，重新组织排布，保持原图风格与辨识度。\"}], \"palettes\": [\"沿用参考图配色；无参考图时采用协调自然配色\", \"奶油色与柔和浅色\", \"莫兰迪低饱和配色\", \"蓝白配色\", \"复古暖色\", \"黑白配色\", \"清新绿白配色\", \"明快鲜艳配色\"], \"base\": \"输出用于布料印花的平面花型原稿：正面平视、清晰干净、细节完整。只输出设计本身，不显示衣服、模特、布料褶皱、房间或产品展示，不添加文字、标志、水印、尺寸标注及外边框。图案疏密和留白均衡，配色适合印花。\", \"reference\": \"如附有参考图片，优先保留其主要元素、造型与配色，按所选连续方式重新排布；参考图中的无关背景和展示场景不带入花型原稿。\"},serverId:\"cloud-v1\",entryOrigin:null};</script>\n  <script src=\"/static/workflow.js\"></script>\n<footer style=\"padding:20px;text-align:center\">云端版本 cloud-1.0.4 · <span id=\"desktopVersion\">画图服务：正在读取版本</span> · <a href=\"/monitor\">运行监控</a> · <a href=\"/report-bug\">报告 Bug</a></footer><script>async function cloudState(){try{const r=await fetch('/api/latest',{cache:'no-store'});if(!r.ok)throw Error();const d=await r.json();document.getElementById('desktopVersion').textContent=d.ready?('画图服务：'+(d.worker_version||'尚未上报版本，请重启画图服务')):('画图服务离线；上次版本：'+(d.worker_version||'未知'));document.getElementById('cloudWorkerState').textContent=d.ready?'虚拟机在线，可以生成图片':'虚拟机暂未连接；可以提交任务，恢复后自动执行'}catch{document.getElementById('cloudWorkerState').textContent='云端连接暂时中断，正在重试'}}cloudState();setInterval(cloudState,5000);</script></body></html>\n";
export const workflow="(function () {\n  'use strict';\n  const terminal = new Set(['done', 'error', 'not_generated']);\n  const names = {pending:'正在提交', queued:'排队中', running:'正在执行', review:'等待人工确认', done:'图片生成成功', not_generated:'本次未生成图片', error:'程序执行失败'};\n  const uid = () => {\n    if(globalThis.crypto?.randomUUID)return crypto.randomUUID().replaceAll('-', '');\n    const bytes=new Uint8Array(16);\n    if(globalThis.crypto?.getRandomValues)crypto.getRandomValues(bytes);else for(let i=0;i<16;i++)bytes[i]=Math.floor(Math.random()*256);\n    return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');\n  };\n  function addReferences(current, files, makeURL) {\n    if (current.length + files.length > 3) throw new Error('每个任务最多 3 张参考图片，已达到上限。请先删除图片再添加。');\n    if (files.some(f => f.size > 20*1024*1024 || !['image/png','image/jpeg','image/webp'].includes(f.type))) throw new Error('请选择不超过 20 MB 的 PNG、JPEG 或 WEBP 图片。');\n    return [...current, ...files.map(file => ({key:uid(), file, url:makeURL(file), uploadId:null}))];\n  }\n  function snapshotDraft(prompt, tool, references) {\n    const requestId=uid();\n    return {taskId:requestId, submitted_at:Date.now()/1000, result:null, request_id:requestId, prompt, tool, referenceImages:references.map(r => ({...r})), upload_ids:[], status:'pending', id:null, stage:'正在提交', error:null};\n  }\n  function presetPrompt(catalog, tool, layout, theme, palette, hasReference) {\n    if (tool.id === 'custom') return '';\n    if (tool.id !== 'fabric') return tool.id === 'seamless' && !hasReference\n      ? tool.instruction.replace('根据参考图或文字', '根据文字').replace('保留主要纹样、配色与风格', '采用协调自然的纹样、配色与风格') : tool.instruction;\n    const chosenPalette = palette === catalog.palettes[0] ? (hasReference ? '沿用参考图配色' : '采用协调自然配色') : palette;\n    const chosenTheme = theme.id === 'reference' && !hasReference ? '根据文字要求原创纹样，造型清晰，配色协调。' : theme.instruction;\n    return [layout.instruction, '纹样主题：'+chosenTheme, '配色：'+chosenPalette+'。', catalog.base, hasReference ? catalog.reference : ''].filter(Boolean).join('\\n\\n');\n  }\n  if (typeof module !== 'undefined') module.exports = {addReferences, snapshotDraft, presetPrompt, terminal};\n  if (typeof document === 'undefined') return;\n  const config = window.workflowConfig;\n  const catalog = config.catalog;\n  const $ = id => document.getElementById(id);\n  const storageKey = 'image-helper-cloud-v1';\n  let references = [], tasks = [], selected = null, modalTarget = null, submittingChain = Promise.resolve();\n  let heartbeatId = config.serverId, heartbeatBusy = false, polling = false, ready = window.parent === window;\n  let generatedPreset = null;\n  const downloadedIds=new Set();\n  try{JSON.parse(localStorage.getItem('image-helper-downloaded-v1')||'[]').forEach(id=>downloadedIds.add(id));}catch(_){}\n  [['fabricTool',catalog.tools],['fabricLayout',catalog.layouts],['fabricTheme',catalog.themes]].forEach(([id, rows]) => rows.forEach(r => $(id).add(new Option(r.label, r.id))));\n  catalog.palettes.forEach(p => $('fabricPalette').add(new Option(p,p)));\n  $('fabricTool').value = 'fabric';\n  function persist() {\n    const state = {schema:2, downloadedIds:[...downloadedIds], acknowledgedAlerts:[...acknowledgedAlerts], successfulTaskTime, tasks:tasks.map(t => ({...t, downloading:false, referenceImages:t.referenceImages.map(r => ({key:r.key, uploadId:r.uploadId, name:r.file?.name || r.name}))})), selected, draft:{prompt:$('prompt').value,tool:$('fabricTool').value}};\n    try { sessionStorage.setItem(storageKey, JSON.stringify(state)); } catch (_) {}\n    if (ready && config.entryOrigin && window.parent !== window) window.parent.postMessage({type:'fabric-task-state',state},config.entryOrigin);\n  }\n  let inputWarning=null, connectionWarning=null, connectionFailures=0;\n  const announced=new Set(), dismissed=new Set();\n  const acknowledgedAlerts=new Set();\n  let successfulTaskTime=0;\n  function rememberAlerts() {\n    try{localStorage.setItem('image-helper-alerts-v1',JSON.stringify({acknowledgedAlerts:[...acknowledgedAlerts],successfulTaskTime}));}catch(_){}\n  }\n  function mergeAlertPreferences(state) {\n    if(!state || typeof state!=='object')return;\n    if(Array.isArray(state.acknowledgedAlerts))state.acknowledgedAlerts.forEach(key=>{if(typeof key==='string')acknowledgedAlerts.add(key);});\n    const time=Number(state.successfulTaskTime);\n    if(Number.isFinite(time)&&time>successfulTaskTime)successfulTaskTime=time;\n  }\n  try{mergeAlertPreferences(JSON.parse(localStorage.getItem('image-helper-alerts-v1')||'null'));}catch(_){}\n  function taskTime(t){return Number(t.created_at||t.submitted_at)||0;}\n  function rememberSuccesses(records) {\n    const previous=successfulTaskTime;\n    records.filter(t=>t.status==='done').forEach(t=>{successfulTaskTime=Math.max(successfulTaskTime,taskTime(t));});\n    if(successfulTaskTime!==previous)rememberAlerts();\n  }\n  function oldErrorIsResolved(t) {\n    const time=taskTime(t);\n    if(time && successfulTaskTime>time)return true;\n    // Older saved drafts may have no timestamp; use their submission order.\n    if(!time)return tasks.slice(tasks.indexOf(t)+1).some(later=>later.status==='done');\n    return false;\n  }\n  let activeWarning=null, voiceEnabled=true;\n  try { voiceEnabled=localStorage.getItem('image-helper-voice')!=='off'; } catch (_) {}\n  $('voiceEnabled').checked=voiceEnabled;\n  function speak(message) {\n    if(!voiceEnabled || !window.speechSynthesis || !window.SpeechSynthesisUtterance)return;\n    const utterance=new SpeechSynthesisUtterance(message);\n    utterance.lang='zh-CN';utterance.rate=1;\n    const chinese=speechSynthesis.getVoices().find(v=>/^zh(-|_)/i.test(v.lang));\n    if(chinese)utterance.voice=chinese;\n    speechSynthesis.cancel();speechSynthesis.speak(utterance);\n  }\n  function warningForTask(t) {\n    if(t.status==='review')return {key:t.request_id+':review:'+t.review_version,task:t,\n      text:'需要人工确认：请查看截图，选择“已经生成”“继续等待”或“生成已结束”。',\n      voice:'请查看界面，选择是否下载图片。已经生成，请点击已经生成；还在生成，请点击继续等待。'};\n    const key=(t.id||t.request_id)+':error:'+(t.submitError||t.error);\n    if((t.submitError || t.status==='error')&&!acknowledgedAlerts.has(key)&&!oldErrorIsResolved(t))return {key,task:t,\n      text:'任务出现问题：'+(t.submitError||t.error||t.stage||'请查看任务详情。'),\n      voice:'任务出现问题，请查看界面的红色提示。'};\n    return null;\n  }\n  function refreshWarning() {\n    rememberSuccesses(tasks);\n    const warning=inputWarning || tasks.map(warningForTask).find(w=>w?.task.status==='review') ||\n      tasks.map(warningForTask).find(w=>w&&!dismissed.has(w.key)) || (connectionWarning&&!dismissed.has(connectionWarning.key)?connectionWarning:null);\n    if(!warning && activeWarning)window.speechSynthesis?.cancel();\n    activeWarning=warning||null;\n    $('attentionBanner').hidden=!warning;\n    document.body.classList.toggle('needs-attention',!!warning);\n    $('attentionText').textContent=warning?.text||'';\n    $('viewAttentionTask').hidden=!warning?.task;\n    const reportLink=$('reportAttention');if(reportLink){reportLink.hidden=!warning||warning.task?.status==='review';reportLink.href='/report-bug?'+new URLSearchParams({task_id:warning?.task?.id||'',error:warning?.task?.error||warning?.text||''});}\n    $('dismissAttention').hidden=!warning || warning.task?.status==='review';\n    if(warning && !announced.has(warning.key)){\n      announced.add(warning.key);speak(warning.voice);\n    }\n  }\n  $('dismissAttention').onclick=()=>{\n    if(!activeWarning)return;\n    dismissed.add(activeWarning.key);\n    if(activeWarning.task && (activeWarning.task.status==='error'||activeWarning.task.submitError)){\n      acknowledgedAlerts.add(activeWarning.key);rememberAlerts();\n    }\n    if(activeWarning===inputWarning)inputWarning=null;\n    if(activeWarning===connectionWarning)connectionWarning=null;\n    refreshWarning();persist();\n  };\n  $('voiceEnabled').onchange=()=>{\n    voiceEnabled=$('voiceEnabled').checked;\n    try{localStorage.setItem('image-helper-voice',voiceEnabled?'on':'off');}catch(_){}\n    if(!voiceEnabled)window.speechSynthesis?.cancel();\n    else speak(activeWarning?.voice||'语音提醒已开启。需要操作时，请留意界面提示。');\n  };\n  $('repeatAttention').onclick=()=>speak(activeWarning?.voice||'语音提醒已开启。需要操作时，请留意界面提示。');\n  $('viewAttentionTask').onclick=()=>{\n    if(!activeWarning?.task)return;\n    selected=activeWarning.task.request_id;render();persist();\n    $('resultTitle').scrollIntoView({behavior:'smooth',block:'start'});\n  };\n  function error(message) {\n    $('errorMessage').textContent=message||'';$('errorMessage').hidden=!message;\n    inputWarning=message?{key:'input:'+message,text:message,\n      voice:/需要先上传|必须上传/.test(message)?'请上传参考图片。当前工具需要参考图片才能开始。':message}:null;\n    if(inputWarning){announced.delete(inputWarning.key);dismissed.delete(inputWarning.key);}\n    refreshWarning();\n  }\n  async function request(path, options={}, timeout=15000) {\n    const controller = new AbortController();\n    const timer = setTimeout(() => controller.abort(), timeout);\n    try {\n      const response = await fetch(path,{...options,signal:controller.signal,cache:'no-store'});\n      const data = await response.json();\n      if (!response.ok) { const e = new Error(data.error || '请求失败'); e.status=response.status; throw e; }\n      return data;\n    } finally { clearTimeout(timer); }\n  }\n  const post = (path,data) => request(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});\n  function applyPreset() {\n    const tool = catalog.tools.find(r => r.id === $('fabricTool').value);\n    if (tool.id === 'custom') { generatedPreset=null; render(); persist(); return; }\n    $('prompt').value = presetPrompt(catalog,tool,catalog.layouts.find(r=>r.id===$('fabricLayout').value),catalog.themes.find(r=>r.id===$('fabricTheme').value),$('fabricPalette').value,references.length>0);\n    generatedPreset = $('prompt').value;\n    render(); persist();\n  }\n  function referenceChanged() {\n    if (generatedPreset !== null && $('prompt').value === generatedPreset) applyPreset();\n    renderReferences(); render();\n  }\n  function renderReferences() {\n    $('referencePreviews').replaceChildren();\n    references.forEach((r,index) => {\n      const card=document.createElement('div'); card.className='reference-card';\n      const img=document.createElement('img'); img.src=r.url; img.alt='参考图片 '+(index+1);\n      const label=document.createElement('span'); label.textContent=r.file.name;\n      const button=document.createElement('button'); button.type='button'; button.className='secondary'; button.textContent='删除第 '+(index+1)+' 张';\n      button.onclick=()=>{ URL.revokeObjectURL(r.url); references=references.filter(x=>x.key!==r.key); error(''); referenceChanged(); };\n      card.append(img,label,button); $('referencePreviews').append(card);\n    });\n    $('referenceName').textContent = references.length+' / 3 张 · 每张最大 20 MB，可单独删除并重新添加。';\n  }\n  $('referenceFile').onchange=()=>{\n    try { references=addReferences(references,Array.from($('referenceFile').files),f=>URL.createObjectURL(f)); error(''); referenceChanged(); }\n    catch(e) { error(e.message); }\n    $('referenceFile').value='';\n  };\n  function current() { return tasks.find(t=>t.request_id===selected); }\n  function downloadKey(t){return t.id||t.request_id;}\n  async function downloadTask(t) {\n    if(!t?.image_url||t.status!=='done'||t.downloading)return;\n    t.downloading=true;render();\n    const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),120000);\n    try{\n      const response=await fetch(t.image_url,{cache:'no-store',signal:controller.signal});\n      if(!response.ok)throw new Error('下载失败，请稍后重试。');\n      const blob=await response.blob();\n      if(!blob.size || !/^image\\//i.test(blob.type))throw new Error('未获取到有效图片，请重试下载。');\n      const url=URL.createObjectURL(blob), link=document.createElement('a');\n      link.href=url;link.download=t.image_filename||'生成图片.png';link.hidden=true;\n      document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);\n      downloadedIds.add(downloadKey(t));\n      try{localStorage.setItem('image-helper-downloaded-v1',JSON.stringify([...downloadedIds]));}catch(_){}\n      error('');persist();\n    }catch(e){error(e.name==='AbortError'?'下载超时，图片仍保留在已完成待下载区，请重试。':e.message);}\n    finally{clearTimeout(timer);t.downloading=false;render();}\n  }\n  $('downloadLink').onclick=event=>{event.preventDefault();downloadTask(current());};\n  function renderTaskSections() {\n    const active=tasks.filter(t=>['pending','queued','running','review'].includes(t.status));\n    const completed=tasks.filter(t=>t.status==='done'&&!downloadedIds.has(downloadKey(t)));\n    $('queuedCount').textContent=active.length;$('completedCount').textContent=completed.length;\n    [['queuedList','queuedEmpty',active],['completedList','completedEmpty',completed]].forEach(([id,empty,rows])=>{\n      $(id).replaceChildren();$(empty).hidden=rows.length>0;\n      rows.slice().reverse().forEach(t=>{\n        const card=document.createElement('article');card.className='work-task';card.dataset.status=t.status;\n        const state=document.createElement('span');state.className='badge';state.dataset.status=t.status;state.textContent=names[t.status];\n        const prompt=document.createElement('p');prompt.textContent=t.prompt;\n        const meta=document.createElement('small');meta.textContent=t.referenceImages.length+' 张参考图'+(t.queue_position?' · 队列位置 '+t.queue_position:'');\n        const actions=document.createElement('div');actions.className='work-task-actions';\n        const view=document.createElement('button');view.type='button';view.className='secondary';view.textContent=t.status==='review'?'查看并确认':'查看任务';\n        view.onclick=()=>{selected=t.request_id;render();persist();$('resultTitle').scrollIntoView({behavior:'smooth',block:'start'});};actions.append(view);\n        if(t.status==='done'){\n          const download=document.createElement('button');download.type='button';download.className='secondary';download.textContent=t.downloading?'正在下载…':'下载图片';download.disabled=!!t.downloading;download.onclick=()=>downloadTask(t);actions.append(download);\n        }\n        if(t.status==='pending'&&t.submitError){\n          const retry=document.createElement('button');retry.type='button';retry.className='secondary';retry.textContent='恢复提交';retry.onclick=()=>enqueueSubmit(t);actions.append(retry);\n        }\n        card.append(state,prompt,meta,actions);$(id).append(card);\n      });\n    });\n  }\n  function render() {\n    const tool=catalog.tools.find(r=>r.id===$('fabricTool').value);\n    document.querySelector('.preset-grid').hidden=tool.id!=='fabric';\n    document.querySelector('.examples').hidden=tool.id==='custom';\n    $('applyPreset').hidden=tool.id==='custom';\n    $('toolHint').textContent=tool.id==='custom'?'纯自定义模式：输入内容原样发送，参考图片可选。':tool.requires_reference?'此工具必须上传至少一张参考图片。':'没有参考图片也可直接按文字生成。';\n    $('characterCount').textContent=Array.from($('prompt').value).length+' 字';\n    $('submitButton').disabled=!$('prompt').value.trim();\n    $('submitLabel').textContent='提交新任务';\n    renderTaskSections();\n    const t=current();\n    $('statusBadge').textContent=t ? names[t.status] : '等待任务';\n    $('statusBadge').dataset.status=t?.status||'idle';\n    $('stageText').textContent=t?.submitError||t?.stage||'提交后可以立即创建下一个任务。';\n    $('taskId').hidden=!t?.id; $('taskId').textContent=t?.id||'';\n    $('queueText').hidden=!t?.queue_position; $('queueText').textContent='队列位置 '+(t?.queue_position||'');\n    $('reviewActions').hidden=t?.status!=='review';\n    const logLink=$('generationLog');if(logLink){logLink.hidden=!t?.id;logLink.href=t?.id?'/jobs/'+t.id+'/log':'#';}\n    $('resultActions').hidden=!['done','review'].includes(t?.status);\n    $('downloadLink').hidden=t?.status!=='done';\n    $('placeholder').hidden=['done','review'].includes(t?.status);\n    $('resultImage').hidden=!['done','review'].includes(t?.status);\n    const src=t?.status==='review'?t.preview_url:t?.status==='done'?t.image_url:'';\n    if (src && $('resultImage').getAttribute('src')!==src) $('resultImage').src=src;\n    if (!src) $('resultImage').removeAttribute('src');\n    $('previewTitle').textContent=t?.status==='not_generated'?'本次未生成图片':t?.status==='error'?'程序执行失败':'等待生成结果';\n    $('previewDescription').textContent=t?.error||t?.stage||'选择任务查看各自进度。';\n    if(t?.image_url){$('downloadLink').href=t.image_url; $('downloadLink').download=t.image_filename||'生成图片.png';}\n    refreshWarning();\n  }\n  function enqueueSubmit(t) {\n    if(t.submitting || t.id || terminal.has(t.status)) return;\n    t.submitting=true; t.submitError=null;\n    // Only network submission ordering is chained; the composer always stays available.\n    submittingChain=submittingChain.then(()=>submitTask(t)).catch(()=>{});\n  }\n  async function submitTask(t) {\n    try {\n      for (const r of t.referenceImages) {\n        if(r.uploadId) continue;\n        if(!r.file) throw new Error('页面已重新加载，未上传的参考图片无法恢复。请重新选择图片并提交新任务。');\n        const form=new FormData();form.append('image',r.file);form.append('upload_id',r.key);\n        const data=await request('/uploads',{method:'POST',body:form},120000); r.uploadId=data.upload_id; persist();\n      }\n      t.upload_ids=t.referenceImages.map(r=>r.uploadId); persist();\n      const data=await post('/jobs',{prompt:t.prompt,tool:t.tool,request_id:t.request_id,upload_ids:t.upload_ids});\n      t.id=data.id; t.taskId=data.id; t.status=data.status; t.stage='任务已接收';\n      t.referenceImages.forEach(r=>{r.name=r.file?.name||r.name;r.file=null;});\n    } catch(e) {\n      if(e.status && e.status<500 && e.status!==429){t.status='error';t.stage='提交失败';t.error=e.message;}\n      else t.submitError=e.message+'；可恢复提交，使用相同编号防止重复生成。';\n    } finally {t.submitting=false;persist();render();loadHistory();}\n  }\n  $('promptForm').onsubmit=event=>{\n    event.preventDefault(); const tool=catalog.tools.find(r=>r.id===$('fabricTool').value);\n    const prompt=$('prompt').value;\n    if(!prompt.trim()) return;\n    if(tool.requires_reference && !references.length){error('此工具需要先上传参考图片。');return;}\n    const t=snapshotDraft(prompt,tool.id,references);tasks.push(t);selected=t.request_id;\n    error('');persist();render();enqueueSubmit(t);\n  };\n  async function poll() {\n    if(polling)return;polling=true;\n    try { await Promise.all(tasks.filter(t=>t.id&&!terminal.has(t.status)).map(async t=>{\n      try {const data=await request('/jobs/'+encodeURIComponent(t.id));const {referenceImages, ...progress}=data;Object.assign(t,progress);t.networkError=null;}\n      catch(e){t.networkError=e.message;if(e.status===404){t.status='error';t.error='服务器中已无此任务记录，请重新提交。';}}\n    }));\n      if(modalTarget){\n        const pending=tasks.find(t=>t.request_id===modalTarget.requestId);\n        if(!pending || pending.status!=='review' || pending.review_version!==modalTarget.version){$('endDialog').close();modalTarget=null;}\n      }\n      persist();render(); } finally {polling=false;}\n  }\n  async function decide(target,action,confirmed=false) {\n    const t=tasks.find(t=>t.request_id===target.requestId);\n    if(!t || t.status!=='review' || t.review_version!==target.version){error('该截图已更新，请重新选择操作。');return;}\n    if(t.deciding)return;t.deciding=true;\n    try {await post('/jobs/'+encodeURIComponent(t.id)+'/review',{action,version:target.version,confirmed});t.status='running';t.stage=action==='end'?'正在结束任务':action==='retry'?'立即尝试下载':'继续检测完成标记';persist();render();await poll();}\n    catch(e){error(e.message);await poll();}finally{t.deciding=false;}\n  }\n  function target() {const t=current();return t?.status==='review'?{requestId:t.request_id,version:t.review_version}:null;}\n  $('retryDownload').onclick=()=>{const v=target();if(v)decide(v,'retry');};\n  $('keepWaiting').onclick=()=>{const v=target();if(v)decide(v,'wait');};\n  $('endGeneration').onclick=()=>{modalTarget=target();if(modalTarget){$('endDialog').showModal();speak('请再次确认是否结束本次任务。确认结束后，将停止检测并且不下载图片。');}};\n  $('cancelEnd').onclick=()=>{$('endDialog').close();modalTarget=null;};\n  $('confirmEnd').onclick=()=>{const v=modalTarget;$('endDialog').close();modalTarget=null;if(v)decide(v,'end',true);};\n  $('endDialog').addEventListener('cancel',()=>{modalTarget=null;});\n  $('reloadImage').hidden=false; $('reloadImage').onclick=()=>{const t=current();const src=t?.status==='review'?t.preview_url:t?.image_url;if(src)$('resultImage').src=src+(src.includes('?')?'&':'?')+'reload='+Date.now();};\n  $('fabricTool').onchange=()=>{error('');if($('fabricTool').value==='custom' && generatedPreset!==null && $('prompt').value===generatedPreset)$('prompt').value='';generatedPreset=null;render();persist();};\n  $('applyPreset').onclick=applyPreset;\n  $('prompt').oninput=()=>{generatedPreset=null;render();persist();};\n  document.querySelectorAll('.example').forEach(button=>button.onclick=()=>{$('fabricTheme').value=button.dataset.theme;$('fabricTool').value='fabric';applyPreset();});\n  let historyOffset=0, historyTotal=0, historyBusy=false;\n  function selectRecord(record) {\n    let task=tasks.find(t=>t.id===record.id);\n    if(!task){task={...record,request_id:record.id,referenceImages:record.referenceImages.map(id=>({key:id,uploadId:id}))};tasks.push(task);}\n    else {const {referenceImages,...progress}=record;Object.assign(task,progress);}\n    selected=task.request_id;render();persist();\n    $('resultTitle').scrollIntoView({behavior:'smooth',block:'start'});\n  }\n  async function loadHistory() {\n    if(historyBusy)return;historyBusy=true;\n    const requestedOffset=historyOffset, requestedFilter=$('historyFilter').value;\n    try {\n      const data=await request('/history?offset='+requestedOffset+'&limit=20&status='+encodeURIComponent(requestedFilter));\n      if(requestedOffset!==historyOffset||requestedFilter!==$('historyFilter').value)return;\n      rememberSuccesses(data.items);refreshWarning();\n      historyTotal=data.total;\n      $('historyList').replaceChildren();\n      data.items.forEach(record=>{\n        const card=document.createElement('article');card.className='reference';\n        const meta=document.createElement('p');meta.textContent=new Date(record.created_at*1000).toLocaleString('zh-CN')+' · '+(names[record.status]||record.status);\n        const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent=record.prompt.slice(0,65)||'提示词';\n        const prompt=document.createElement('pre');prompt.style.cssText='white-space:pre-wrap;overflow-wrap:anywhere';prompt.textContent=record.prompt;details.append(summary,prompt);\n        card.append(meta,details);\n        if(record.status==='done' && record.image_url){\n          const img=document.createElement('img');img.src=record.image_url;img.loading='lazy';img.alt='生成记录图片';img.style.cssText='width:100%;height:160px;object-fit:contain';card.append(img);\n          const link=document.createElement('a');link.href=record.image_url;link.download=record.image_filename||'生成图片.png';link.className='secondary';link.textContent='下载原图';link.onclick=event=>{event.preventDefault();downloadTask(tasks.find(t=>t.id===record.id)||record);};card.append(link);\n        }\n        const stage=document.createElement('p');stage.textContent=record.error||record.stage;card.append(stage);\n        const open=document.createElement('button');open.type='button';open.className='secondary';open.textContent='查看此任务';open.onclick=()=>selectRecord(record);card.append(open);\n        $('historyList').append(card);\n      });\n      $('historyMessage').textContent=historyTotal?'共 '+historyTotal+' 条记录':'还没有生成记录，提交任务后会自动保存。';\n      $('historyPage').textContent=historyTotal?'第 '+(Math.floor(historyOffset/20)+1)+' / '+Math.ceil(historyTotal/20)+' 页':'';\n      $('historyPrevious').disabled=historyOffset===0;$('historyNext').disabled=historyOffset+20>=historyTotal;\n    } catch(e){$('historyMessage').textContent='记录暂时无法加载：'+e.message+'，请点击刷新记录。';}\n    finally{historyBusy=false;if(requestedOffset!==historyOffset||requestedFilter!==$('historyFilter').value)loadHistory();}\n  }\n  $('historyFilter').onchange=()=>{historyOffset=0;loadHistory();};\n  $('refreshHistory').onclick=loadHistory;\n  $('historyPrevious').onclick=()=>{historyOffset=Math.max(0,historyOffset-20);loadHistory();};\n  $('historyNext').onclick=()=>{if(historyOffset+20<historyTotal){historyOffset+=20;loadHistory();}};\n  async function heartbeat() {\n    if(heartbeatBusy)return;heartbeatBusy=true;const nonce=uid();\n    try {\n      const data=await post('/api/tunnel-heartbeat',{nonce,server_id:heartbeatId});\n      if(data.nonce!==nonce||data.server_id!==heartbeatId)throw new Error('连接校验失败');\n      $('connectionText').textContent='连接正常';\n      if(connectionWarning){announced.delete('connection-lost');dismissed.delete('connection-lost');}connectionFailures=0;connectionWarning=null;$('connection').classList.remove('offline');refreshWarning();\n      if(config.entryOrigin && window.parent!==window)window.parent.postMessage({type:'fabric-app-heartbeat'},config.entryOrigin);\n    } catch(e) {\n      $('connectionText').textContent='正在重新连接';$('connection').classList.add('offline');\n      connectionFailures++;\n      if(connectionFailures>=3){connectionWarning={key:'connection-lost',text:'连接暂时出现问题，正在自动恢复。请稍等，不要重复提交任务。',voice:'连接出现问题，正在自动恢复。请稍等，不要重复提交任务。'};refreshWarning();}\n      if(e.status===409)try{const data=await request('/api/tunnel-heartbeat');heartbeatId=data.server_id;}catch(_){}\n    } finally {heartbeatBusy=false;}\n  }\n  function restore(state) {\n    if(!state || typeof state!=='object')return;\n    mergeAlertPreferences(state);rememberAlerts();\n    if(Array.isArray(state.downloadedIds))state.downloadedIds.forEach(id=>{if(typeof id==='string')downloadedIds.add(id);});\n    if(state.schema===2 && Array.isArray(state.tasks)) {\n      const known=new Set(tasks.map(t=>t.request_id));\n      for(const t of state.tasks){if(!t?.request_id||known.has(t.request_id))continue;tasks.push({...t,referenceImages:Array.isArray(t.referenceImages)?t.referenceImages:[],submitting:false,deciding:false,downloading:false});}\n      selected=selected||state.selected;\n      if(!tasks.some(t=>t.request_id===selected)) selected=tasks[0]?.request_id||null;\n      if(!$('prompt').value && state.draft){$('prompt').value=state.draft.prompt||'';if(catalog.tools.some(t=>t.id===state.draft.tool))$('fabricTool').value=state.draft.tool;}\n    } else if(state.id && !tasks.some(t=>t.id===state.id)) {\n      const t={...state,taskId:state.id,request_id:state.id,referenceImages:[],image_url:state.status==='done'?'/jobs/'+encodeURIComponent(state.id)+'/image':undefined,image_filename:state.imageFilename||'',preview_url:state.previewURL,review_version:state.reviewVersion};tasks.push(t);selected=t.request_id;\n    }\n    tasks.filter(t=>t.status==='pending'&&!t.id).forEach(t=>{t.submitError=t.submitError||'上次提交未完成，请选择恢复提交。';});render();poll();\n  }\n  window.addEventListener('message',event=>{\n    if(event.source!==window.parent||event.origin!==config.entryOrigin||event.data?.type!=='fabric-resume-state')return;\n    ready=true;restore(event.data.state);persist();\n  });\n  try{restore(JSON.parse(sessionStorage.getItem(storageKey)||sessionStorage.getItem('image-helper-current-task-v1')||'null'));}catch(_){}\n  if(!$('prompt').value)applyPreset();\n  renderReferences();render();heartbeat();loadHistory();setInterval(loadHistory,10000);setInterval(heartbeat,5000);setInterval(poll,2000);\n  window.addEventListener('online',()=>{heartbeat();poll();});\n})();\n";
export const catalog={"tools": [{"id": "custom", "label": "自定义提示词", "instruction": "", "requires_reference": false}, {"id": "fabric", "label": "布料花型设计", "instruction": "", "requires_reference": false}, {"id": "extract", "label": "花型提取／印花提取", "requires_reference": true, "instruction": "从上传的布料、服装或家纺照片中提取印花纹样。只保留原图中的花朵、枝叶、几何纹样或其他印花元素，忠实保留造型、线条与配色。去掉布料底色、经纬布纹、纤维肌理、褶皱、光照阴影、服装轮廓、人物及背景；校正透视，使纹样平整正视。恢复被轻微褶皱干扰的线条，尽量完整提取可见元素，不随意改变花型。输出清晰干净的平面纹样图，要求透明背景 PNG，无文字、水印、边框或产品展示。"}, {"id": "seamless", "label": "四方连续图", "requires_reference": false, "instruction": "根据参考图或文字设计四方连续图。保留主要纹样、配色与风格，重新排列为一个正方形循环单元；左右边缘、上下边缘必须准确对应续接，四个角衔接自然，重复平铺后没有明显接缝。只输出一个可平铺的单元，不输出四宫格、网格演示、服装效果图或标注。"}, {"id": "style", "label": "风格转换", "requires_reference": true, "instruction": "以参考图为基础进行艺术风格转换，保留主体结构、图案构成、比例与辨识度，把线条和色彩转为细腻自然的手绘水彩风格。输出正面平视的干净花型原稿，不增加模特、产品展示或无关场景。具体风格可按我下面的补充要求调整。"}, {"id": "edit", "label": "AI 修图 · 自定义", "requires_reference": true, "instruction": "按我描述的要求修改参考图，保持未要求修改的主体、构图、花型和配色一致，只调整指定部分。修复应自然、细节清楚，不擅自添加文字、水印或其他元素。具体修改要求："}, {"id": "remove_texture", "label": "AI 去布纹", "requires_reference": true, "instruction": "去除参考图中的经纬纱线、布纹、纤维肌理、褶皱和光照阴影，同时保留印花图案原有轮廓、细节和配色。校正透视与拉伸变形，让图案成为平整正视、色彩均匀的印花原稿。只清理布料造成的干扰，不把花型内部原本的手绘笔触或设计纹理一并抹掉。"}, {"id": "redraw", "label": "高清重绘", "requires_reference": true, "instruction": "忠实重绘参考图中的花型，保留原有构图、纹样轮廓、配色和元素数量，提高线条清晰度，修复模糊、锯齿与压缩噪点，恢复合理的细节。输出尽可能高分辨率的干净平面原稿，不改变设计、不新增装饰、无文字或水印。"}, {"id": "expand", "label": "扩图", "requires_reference": true, "instruction": "在参考图周围自然扩展画面，保持原始区域、风格、配色、纹样大小和密度一致，新增内容与原图连续衔接，不重复明显的局部，不出现突兀边界。用于布料花型时只扩展平面花型，不生成服装、模特或产品场景。扩展方向及比例按补充要求执行。"}, {"id": "similar", "label": "相似花型再设计", "requires_reference": true, "instruction": "参考原图的主题、配色、艺术风格、纹样尺度与密度，重新设计一张协调但有变化的布料花型。保留整体风格，适度改变元素姿态、细节和排列方式，输出单张新设计的平面原稿，无产品展示、文字或水印。"}, {"id": "remove_rhinestones", "label": "去除烫钻", "requires_reference": true, "instruction": "去除参考图中的烫钻、亮片及其高光反射，修复被遮挡的原有印花线条与色彩，保持主要图案的造型、布局和配色。修补区域与周围自然一致，不生成新的闪光颗粒、金属点或额外装饰。"}, {"id": "vector_style", "label": "矢量风格重绘 · 图片", "requires_reference": true, "instruction": "把参考图重绘为干净的矢量插画视觉风格：轮廓清晰、曲线平滑、色块干净、颜色层次简洁，忠实保留主要造型与配色。输出单张平面图片，方便后续描摹矢量化；不生成文件界面、格式标签、文字或水印。"}, {"id": "cutout", "label": "抠图 · 单图", "requires_reference": true, "instruction": "精细提取参考图中的主体或印花元素，移除无关背景，保留主体完整轮廓、细节、边缘与原有色彩；不留背景残片、白边或锯齿。输出透明背景 PNG，不添加阴影、文字、水印或外框。"}, {"id": "try_on", "label": "服装换装效果", "requires_reference": true, "instruction": "以参考图片中的人物或模特为基础，根据我的服装描述更换穿着，保留人物身份、面部、姿态、身材比例及原有场景。服装结构和布料纹样贴合身体，褶皱、光线与遮挡自然。服装或花型要求："}, {"id": "hanging", "label": "服装挂拍／立体效果", "requires_reference": true, "instruction": "参考服装或花型图片，生成一张干净专业的服装挂拍或立体商品展示图片。保留服装款式、剪裁、主要配色及纹样，比例准确，面料和光照自然，背景简洁，边缘清楚。具体服装品类、角度及背景要求："}, {"id": "scene", "label": "参考场景再设计", "requires_reference": true, "instruction": "参考上传图片的构图、场景、光照与整体风格，根据我的要求生成新的场景或商品展示图。画面完整、比例自然，保留需要参考的主要特征；不添加无关文字、水印、界面元素或商标。具体要求："}], "layouts": [{"id": "four_way", "label": "四方连续 · 无缝平铺", "instruction": "设计可印在布料上的四方连续花型，输出一张正方形循环单元。左右边缘、上下边缘的图案、位置及颜色必须衔接，横向和纵向重复平铺后自然连续，不出现拼接缝。边缘切开的元素要在对侧对应续接。不要画四宫格或多张拼接示意图。"}, {"id": "horizontal", "label": "二方连续 · 横向", "instruction": "设计布料用横向二方连续花型，输出一张横向循环单元。左右边缘的图案及颜色必须对应衔接，横向重复时自然连续；上下边缘保持完整，不要求纵向循环。"}, {"id": "vertical", "label": "二方连续 · 纵向", "instruction": "设计布料用纵向二方连续花型，输出一张纵向循环单元。上下边缘的图案及颜色必须对应衔接，纵向重复时自然连续；左右边缘保持完整，不要求横向循环。"}, {"id": "half_drop", "label": "半落位连续 · 错位排列", "instruction": "设计布料用半落位连续花型，相邻列中的主纹样错开半个排列节距，节奏自然。将错位排列完整收纳到一张矩形循环单元中，使最终单元上下左右都能直接衔接平铺，无明显接缝；不画拼接示意图。"}, {"id": "placement", "label": "定位花 · 单独图案", "instruction": "设计布料用定位花图案：一个完整的主花型，主次分明、构图完整，周围保留适当留白。主图案不要被边缘裁切，适合放在衣片、围巾或布料指定位置；输出单个完整设计。"}, {"id": "border", "label": "边饰 · 连续花边", "instruction": "设计布料用连续边饰花型，装饰纹样沿横向形成清楚的花边层次，左右边缘必须能重复衔接，横向平铺自然连续。上下边缘保持整洁，适合布料边缘或裙摆的装饰带。"}], "themes": [{"id": "ditsy", "label": "小碎花", "instruction": "细小的花朵、花苞与纤细枝叶，元素大小有变化，疏密均衡，清新细腻，适合连衣裙与轻薄布料。"}, {"id": "large_floral", "label": "大花卉", "instruction": "大朵花卉与舒展枝叶，层次清楚，花型错落排布，优雅且有装饰感，适合服装与家纺。"}, {"id": "botanical", "label": "植物枝叶", "instruction": "自然舒展的叶片、枝条与小花，植物形态细腻，方向有变化，整体平衡，清新自然。"}, {"id": "tropical", "label": "热带植物", "instruction": "龟背竹、棕榈叶与热带花卉，舒展而有层次，明快但配色协调，具有夏日气息。"}, {"id": "geometric", "label": "几何图案", "instruction": "圆形、弧线、三角形和简洁几何块面，线条清晰，排列有节奏，现代而简洁。"}, {"id": "stripes", "label": "条纹", "instruction": "宽窄搭配的条纹，间距和粗细有清晰规律，线条干净，适合服装印花；不要加入文字或标志。"}, {"id": "dots", "label": "波点", "instruction": "大小协调的圆形波点，排列规律或轻微错落，整体密度均衡，干净简洁、经典耐看。"}, {"id": "checks", "label": "格纹", "instruction": "经纬交织感的格纹，线宽和间距有清晰规律，色块边界干净，经典织物风格。"}, {"id": "kids", "label": "童趣动物", "instruction": "简洁可爱的动物、小星星与小植物，轮廓清楚，造型温和，元素错落但不过密，适合童装与儿童家纺。"}, {"id": "fruit", "label": "水果花型", "instruction": "柠檬、草莓或其他协调搭配的水果，辅以小叶片和花朵，生动清新，适合夏季服装与餐厨布料。"}, {"id": "paisley", "label": "佩斯利腰果花", "instruction": "经典佩斯利腰果纹与细密装饰花纹，弧线流畅，主纹样和小纹样搭配，精致有序。"}, {"id": "abstract", "label": "抽象肌理", "instruction": "抽象笔触、点线与柔和色块，保留绘画感但画面干净，层次自然，适合艺术感布料印花。"}, {"id": "reference", "label": "参考图再设计", "instruction": "保留参考图的主要纹样、主体造型与配色，提取可用于布料的元素，重新组织排布，保持原图风格与辨识度。"}], "palettes": ["沿用参考图配色；无参考图时采用协调自然配色", "奶油色与柔和浅色", "莫兰迪低饱和配色", "蓝白配色", "复古暖色", "黑白配色", "清新绿白配色", "明快鲜艳配色"], "base": "输出用于布料印花的平面花型原稿：正面平视、清晰干净、细节完整。只输出设计本身，不显示衣服、模特、布料褶皱、房间或产品展示，不添加文字、标志、水印、尺寸标注及外边框。图案疏密和留白均衡，配色适合印花。", "reference": "如附有参考图片，优先保留其主要元素、造型与配色，按所选连续方式重新排布；参考图中的无关背景和展示场景不带入花型原稿。"};
